// Nimmt die hochgeladene Scan-Datei und legt sie unter dem festen Namen "data" ab,
// damit der Vision-Schritt sie unabhängig vom Feldnamen des Formulars findet.
const item = $input.first();
const binaer = item.binary ?? {};
const schluessel = Object.keys(binaer);
if (schluessel.length === 0) {
  throw new Error('Kein Scan erhalten. Bitte ein Bild (JPG oder PNG) der Verordnung hochladen.');
}
const datei = binaer[schluessel[0]];
const typ = String(datei.mimeType || '');
if (!typ.startsWith('image/')) {
  throw new Error('Der Scan muss ein Bild sein (JPG oder PNG), erhalten: ' + (typ || 'unbekannt') + '. PDF-Scans bitte als Bild speichern.');
}
return [{ json: { dateiname: datei.fileName ?? null, mimeType: typ }, binary: { data: datei } }];

// Liest die Antwort des Vision-Schritts, prüft jeden Wert gegen die erlaubten
// Formularwerte und bereitet die Vorbelegung für die Kontrollseite vor.
// Nichts wird geraten: Unpassendes bleibt leer und wird als "unsicher" markiert.
const DROPDOWNS = {"versichertenstatus": ["Mitglied", "Familienangehöriger", "Rentner"], "heilmittelbereich": ["Physiotherapie", "Podologische Therapie", "Stimm-, Sprech-, Sprach- und Schlucktherapie", "Ergotherapie", "Ernährungstherapie"], "zuzahlung": ["Zuzahlung frei", "Zuzahlungspflichtig"], "unfallfolgen": ["nein", "ja"], "bvg_ser": ["nein", "ja"], "leitsymptomatik": ["a", "b", "c", "x – patientenindividuell"], "therapiebericht": ["nein", "ja"], "hausbesuch": ["nein", "ja"], "dringlich": ["nein", "ja"]};
const FELDER = [["krankenkasse", "text", "Krankenkasse bzw. Kostenträger"], ["nachname", "text", "Nachname der versicherten Person"], ["vorname", "text", "Vorname"], ["geburtsdatum", "date", "Geburtsdatum"], ["kostentraegerkennung", "text", "Kostenträgerkennung"], ["versichertennummer", "text", "Versicherten-Nr."], ["versichertenstatus", "dropdown", "Status"], ["bsnr", "text", "Betriebsstätten-Nr. (BSNR, 9-stellig)"], ["lanr", "text", "Arzt-Nr. (LANR, 9-stellig)"], ["ausstellungsdatum", "date", "Ausstellungsdatum"], ["heilmittelbereich", "dropdown", "Heilmittelbereich"], ["zuzahlung", "dropdown", "Zuzahlung"], ["unfallfolgen", "dropdown", "Unfallfolgen (sonstiger Unfall, keine Arbeitsunfälle)"], ["bvg_ser", "dropdown", "BVG / SER (besonderer Versorgungsbedarf)"], ["icd10", "text", "ICD-10-Code Zeile 1 (Anlass der Verordnung)"], ["icd10_bezeichnung", "text", "Bezeichnung zu Zeile 1"], ["icd10_2", "text", "ICD-10-Code Zeile 2 (optional, z. B. Diagnoseliste)"], ["icd10_2_bezeichnung", "text", "Bezeichnung zu Zeile 2"], ["diagnosegruppe", "text", "Diagnosegruppe (z. B. WS, EX)"], ["leitsymptomatik", "dropdown", "Leitsymptomatik gemäß Heilmittelkatalog"], ["leitsymptomatik_freitext", "textarea", "Leitsymptomatik als Freitext (bei x)"], ["heilmittel_1", "text", "Heilmittel 1 (z. B. KG)"], ["einheiten_1", "number", "Behandlungseinheiten Heilmittel 1"], ["heilmittel_2", "text", "Heilmittel 2"], ["einheiten_2", "number", "Behandlungseinheiten Heilmittel 2"], ["heilmittel_3", "text", "Heilmittel 3"], ["einheiten_3", "number", "Behandlungseinheiten Heilmittel 3"], ["ergaenzendes_heilmittel", "text", "Ergänzendes Heilmittel"], ["einheiten_ergaenzend", "number", "Behandlungseinheiten ergänzendes Heilmittel"], ["frequenz", "text", "Therapiefrequenz (z. B. 2x pro Woche)"], ["therapiebericht", "dropdown", "Therapiebericht erforderlich"], ["hausbesuch", "dropdown", "Hausbesuch erforderlich"], ["dringlich", "dropdown", "Dringlicher Behandlungsbedarf (Beginn innerhalb 14 Tagen)"], ["therapieziele", "textarea", "Therapieziele / weitere Hinweise"]];

function textAus(o) {
  if (o === null || o === undefined) return '';
  if (typeof o === 'string') return o;
  if (Array.isArray(o)) return o.map(textAus).filter(Boolean).join('\n');
  for (const k of ['content', 'text', 'output_text', 'message', 'output']) {
    if (o[k] !== undefined) { const t = textAus(o[k]); if (t) return t; }
  }
  return JSON.stringify(o);
}

const roh = textAus($input.first().json);
let gelesen = { felder: {}, unsicher: [] };
let lesefehler = null;
try {
  const a = roh.indexOf('{'), b = roh.lastIndexOf('}');
  gelesen = JSON.parse(roh.slice(a, b + 1));
} catch (e) {
  lesefehler = 'Der Scan konnte nicht ausgewertet werden – bitte alle Felder von Hand ausfüllen.';
}

const quelle = gelesen.felder ?? {};
const unsicher = new Set(Array.isArray(gelesen.unsicher) ? gelesen.unsicher : []);
const felder = {};
// Platzhalter, die Modelle statt eines leeren Werts schreiben
const LEER = /^(null|none|n\/a|-|–|—|leer|nicht angegeben|keine angabe)?$/i;

const isoDatum = (v) => {
  const t = String(v ?? '').trim();
  const de = /^(\d{1,2})\.(\d{1,2})\.(\d{2,4})$/.exec(t);
  if (de) { const j = de[3].length === 2 ? '20' + de[3] : de[3]; return j + '-' + de[2].padStart(2, '0') + '-' + de[1].padStart(2, '0'); }
  return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : '';
};

for (const [name, typ] of FELDER) {
  let v = quelle[name];
  if (v === null || v === undefined || LEER.test(String(v).trim())) { felder[name] = ''; continue; }
  v = String(v).trim();
  if (name === 'versichertenstatus') {
    const ziffer = { '1': 'Mitglied', '3': 'Familienangehöriger', '5': 'Rentner' }[v.replace(/\D/g, '').charAt(0)];
    if (ziffer) { felder[name] = ziffer; unsicher.delete(name); continue; }
  }
  if (typ === 'date') {
    const d = isoDatum(v);
    if (!d) unsicher.add(name);
    v = d;
  } else if (typ === 'number') {
    const n = Number(v.replace(',', '.'));
    if (!Number.isFinite(n)) { unsicher.add(name); v = ''; } else v = String(n);
  } else if (typ === 'dropdown') {
    const optionen = DROPDOWNS[name] || [];
    let treffer = optionen.find((o) => o.toLowerCase() === v.toLowerCase());
    if (!treffer && name === 'leitsymptomatik') treffer = optionen.find((o) => o.charAt(0) === v.charAt(0).toLowerCase());
    if (!treffer) { unsicher.add(name); v = ''; } else v = treffer;
  } else if (name === 'bsnr' || name === 'lanr') {
    v = v.replace(/\s/g, '');
    if (!/^\d{9}$/.test(v)) unsicher.add(name);
  } else if (name.startsWith('icd10') && !name.endsWith('bezeichnung')) {
    v = v.toUpperCase().replace(/\s/g, '');
  } else if (name === 'diagnosegruppe') {
    v = v.toUpperCase();
  }
  felder[name] = v;
}

const labels = Object.fromEntries(FELDER.map(([n, , l]) => [n, l]));
const liste = [...unsicher].filter((n) => labels[n]).map((n) => labels[n]);
const hinweis = lesefehler
  ? lesefehler
  : 'Vom Scan übernommen. Bitte jede Angabe mit dem Original vergleichen und korrigieren, dann prüfen lassen.'
    + (liste.length ? ' Nicht sicher gelesen: ' + liste.join(', ') + '.' : '');

return [{ json: { felder, unsicher: [...unsicher], hinweis, lesefehler: !!lesefehler } }];

// Backup (Scan): Bildet die geprüften Formularfelder auf das Verordnung-Schema des Prüf-Workflows ab.
// Fehlende Angaben werden null – geraten wird nichts.
const f = $input.first().json;

const text = (v) => (v === undefined || v === null || String(v).trim() === "" ? null : String(v).trim());
const zahl = (v) => {
  const t = String(v ?? "").replace(",", ".").trim();
  if (!t) return null;
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
};
const iso = (v) => {
  const t = text(v);
  if (!t) return null;
  const de = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(t);
  if (de) return de[3] + "-" + de[2].padStart(2, "0") + "-" + de[1].padStart(2, "0");
  return t.slice(0, 10);
};

const bereiche = {
  "Physiotherapie": "physiotherapie",
  "Podologische Therapie": "podologie",
  "Stimm-, Sprech-, Sprach- und Schlucktherapie": "ssss",
  "Ergotherapie": "ergotherapie",
  "Ernährungstherapie": "ernaehrung"
};
const ls = text(f.leitsymptomatik);

const heilmittel = [];
for (const i of [1, 2, 3]) {
  const name = text(f["heilmittel_" + i]);
  if (name) heilmittel.push({ name, einheiten: zahl(f["einheiten_" + i]), art: "vorrangig" });
}
const ergaenzend = text(f.ergaenzendes_heilmittel);

const jetzt = new Date();
const heute = jetzt.toISOString().slice(0, 10);
const uhrzeit = String(jetzt.getHours()).padStart(2, "0") + String(jetzt.getMinutes()).padStart(2, "0");
const krankenkasse = text(f.krankenkasse);
const code2 = (text(f.icd10_2) || "").toUpperCase() || null;

const verordnung = {
  verordnung_ref: "VO-" + heute.replace(/-/g, "") + "-" + uhrzeit,
  patient: {
    krankenkasse,
    nachname: text(f.nachname),
    vorname: text(f.vorname),
    geburtsdatum: iso(f.geburtsdatum),
    kostentraegerkennung: text(f.kostentraegerkennung),
    versichertennummer: text(f.versichertennummer),
    versichertenstatus: text(f.versichertenstatus)
  },
  bsnr: text(f.bsnr),
  lanr: text(f.lanr),
  ausstellungsdatum: iso(f.ausstellungsdatum),
  pruefdatum: heute,
  geplanter_beginn: null,
  zuzahlung: text(f.zuzahlung) === "Zuzahlung frei" ? "frei" : text(f.zuzahlung) === "Zuzahlungspflichtig" ? "pflicht" : null,
  unfallfolgen: f.unfallfolgen === "ja",
  bvg_ser: f.bvg_ser === "ja",
  heilmittelbereich: bereiche[text(f.heilmittelbereich)] ?? null,
  icd10: (text(f.icd10) || "").toUpperCase() || null,
  icd10_bezeichnung: text(f.icd10_bezeichnung),
  weitere_diagnosen: code2 ? [{ code: code2, bezeichnung: text(f.icd10_2_bezeichnung) }] : [],
  nicht_verordnungsrelevant: [],
  diagnosen: [
    ...(text(f.icd10) ? [{ code: text(f.icd10).toUpperCase(), bezeichnung: text(f.icd10_bezeichnung), anlass: true }] : []),
    ...(code2 ? [{ code: code2, bezeichnung: text(f.icd10_2_bezeichnung), anlass: false }] : [])
  ],
  diagnosegruppe: (text(f.diagnosegruppe) || "").toUpperCase() || null,
  leitsymptomatik: ls ? ls.charAt(0).toLowerCase() : null,
  leitsymptomatik_freitext: text(f.leitsymptomatik_freitext),
  heilmittel,
  ergaenzendes_heilmittel: ergaenzend ? { name: ergaenzend, einheiten: zahl(f.einheiten_ergaenzend) } : { name: null, einheiten: null },
  frequenz: text(f.frequenz),
  therapiebericht: f.therapiebericht === "ja",
  hausbesuch: f.hausbesuch === "ja",
  dringlich: f.dringlich === "ja",
  therapieziele_hinweise: text(f.therapieziele),
  arzt: { name: null, fachrichtung: null, betriebsstaette: null },
  unterschrift: true,
  letzte_behandlung: null,
  unterbrechungsgrund: null,
  kostentraeger: krankenkasse,
  quelle: "scan"
};

return [{ json: { verordnung } }];

// Entscheidet, ob die Eingabe bereits eine strukturierte Verordnung ist (Formular,
// JSON aus der Praxissoftware) oder Freitext, den der Extraktor lesen muss.
// Strukturierte Eingaben überspringen den LLM-Extraktor – schneller und deterministisch.
const j = $json;
const kandidat =
  j.chatInput ??
  j.body?.verordnung ?? j.body ??
  j.verordnung ??
  j.eingabe?.verordnung ??
  j;

let verordnung = null;
if (typeof kandidat === "string") {
  try {
    const geparst = JSON.parse(kandidat);
    verordnung = geparst && geparst.verordnung ? geparst.verordnung : geparst;
  } catch {
    // kein JSON – bleibt Freitext
  }
} else if (kandidat && typeof kandidat === "object") {
  verordnung = kandidat.verordnung ?? kandidat;
}

const schluessel = ["icd10", "diagnosen", "heilmittel", "ausstellungsdatum", "patient"];
const strukturiert = !!verordnung && schluessel.some((k) => verordnung[k] !== undefined && verordnung[k] !== null);

return [{ json: {
  modus: strukturiert ? "strukturiert" : "freitext",
  verordnung: strukturiert ? verordnung : null,
  text: typeof kandidat === "string" ? kandidat : String(j.chatInput ?? JSON.stringify(kandidat))
} }];

// Reicht die im Formular bzw. von der Praxissoftware gewählte Verordnung an die
// Prüfkette weiter. Die zwei ICD-Zeilen sind hier bereits entschieden – anders als
// beim Freitext, wo "Diagnosen auswählen" sie erst bestimmt.
const vo = { ...$json.verordnung };
const diagnosen = Array.isArray(vo.diagnosen) ? vo.diagnosen : [];

vo.icd10 = vo.icd10 ?? diagnosen[0]?.code ?? null;
vo.icd10_bezeichnung = vo.icd10_bezeichnung ?? diagnosen[0]?.bezeichnung ?? null;
if (!Array.isArray(vo.weitere_diagnosen)) {
  vo.weitere_diagnosen = diagnosen[1] ? [{ code: diagnosen[1].code, bezeichnung: diagnosen[1].bezeichnung ?? null }] : [];
}
vo.nicht_verordnungsrelevant = vo.nicht_verordnungsrelevant ?? [];
vo.quelle = vo.quelle ?? "formular";

return [{ json: { output: vo } }];

const vo = $input.first().json.output;
const d = (s) => (s ? new Date(s + 'T00:00:00Z') : null);
const tage = (a, b) => (a && b ? Math.round((b - a) / 86400000) : null);
const aus = d(vo.ausstellungsdatum);
const pruef = d(vo.pruefdatum);
const beginn = d(vo.geplanter_beginn) || pruef;
const letzte = d(vo.letzte_behandlung);
const grenze = vo.dringlich ? 14 : 28;
const bereitsBegonnen = !!letzte;
const tageBisBeginn = bereitsBegonnen ? null : tage(aus, beginn);
const unterbrechung = letzte ? tage(letzte, beginn) : null;
const hm = Array.isArray(vo.heilmittel) ? vo.heilmittel : [];
// ICD-10-Bereich -> Körperregion (Kapitelstruktur ICD-10-GM, nur Muskel-Skelett; sonst null = LLM prüft mit RAG)
const icdRegion = (code) => {
  if (!code) return null;
  const m = String(code).toUpperCase().match(/^([A-Z])(\d{2})/);
  if (!m) return null;
  const k = m[1], n = Number(m[2]);
  if (k === 'M' && n >= 40 && n <= 54) return 'WS';                 // Krankheiten der Wirbelsäule und des Rückens
  if (k === 'S' && [12, 13, 22, 23, 32, 33].includes(n)) return 'WS'; // Verletzungen Hals-, Brust-, Lendenwirbelsäule
  if (k === 'M' && n >= 15 && n <= 25) return 'EX';                 // Arthrosen und sonstige Gelenkkrankheiten
  if (k === 'M' && [75, 76, 77].includes(n)) return 'EX';           // Schulter, untere Extremität, Enthesopathien
  if (k === 'S' && n >= 40 && n <= 99) return 'EX';                 // Verletzungen Schulter bis Fuß
  return null;
};
const region = icdRegion(vo.icd10);
const dg = vo.diagnosegruppe ? String(vo.diagnosegruppe).toUpperCase().trim() : null;
// Leitsymptomatik je Diagnosegruppe laut Heilmittelkatalog Physiotherapie (WS, EX: a, b, x = patientenindividuell).
// Andere Gruppen oder unklare Werte: null = Prüfer beurteilt mit dem Regelwerk.
const LEITSYMPTOMATIK_KATALOG = { WS: ['a', 'b', 'x'], EX: ['a', 'b', 'x'] };
const ls = vo.leitsymptomatik ? String(vo.leitsymptomatik).trim().toLowerCase() : null;
const leitsymptomatikZulaessig = ls && /^[a-cx]$/.test(ls) && LEITSYMPTOMATIK_KATALOG[dg] ? LEITSYMPTOMATIK_KATALOG[dg].includes(ls) : null;
const ist_marker = (wert) => /^\[[^\]]+\]$/.test(String(wert ?? '').trim());
// Marker = redigiert: Feld ausgefüllt, Format nicht prüfbar (null), nicht fehlerhaft (false).
const formatOk = (wert) => (vorhanden(wert) && !ist_marker(wert) ? /^\d{9}$/.test(String(wert).trim()) : null);
const vorhanden = (wert) => wert !== null && wert !== undefined && String(wert).trim() !== '';
// Pflichtangaben deterministisch aus dem Original – nach der PII-Redaktion stehen bei LANR/BSNR nur Marker.
const pflichtangaben = {
  kostentraeger: vorhanden(vo.patient?.krankenkasse) || vorhanden(vo.kostentraeger),
  lanr: vorhanden(vo.lanr),
  bsnr: vorhanden(vo.bsnr),
  ausstellungsdatum: vorhanden(vo.ausstellungsdatum),
  unterschrift: vo.unterschrift === true,
  icd10: vorhanden(vo.icd10) || (Array.isArray(vo.diagnosen) && vo.diagnosen.length > 0),
  diagnosegruppe: vorhanden(vo.diagnosegruppe),
  leitsymptomatik: vorhanden(vo.leitsymptomatik) || vorhanden(vo.leitsymptomatik_freitext),
  heilmittel_mit_einheiten: hm.some((h) => Number(h.einheiten) > 0),
  frequenz: vorhanden(vo.frequenz)
};
const fakten = {
  frist_grenze_tage: grenze,
  dringlich: !!vo.dringlich,
  bereits_begonnen: bereitsBegonnen,
  tage_ausstellung_bis_beginn: tageBisBeginn,
  beginn_fristgerecht: tageBisBeginn === null ? null : tageBisBeginn <= grenze,
  tage_unterbrechung: unterbrechung,
  unterbrechung_grenze_tage: 14,
  unterbrechung_zulaessig: unterbrechung === null ? null : (unterbrechung <= 14 || !!vo.unterbrechungsgrund),
  summe_einheiten: hm.reduce((s, h) => s + (Number(h.einheiten) || 0), 0),
  // Für die Höchstmenge je Verordnung zählen ergänzende Heilmittel nicht (HeilM-RL § 7 Abs. 5); unbekannte Art zählt vorsichtshalber mit.
  summe_einheiten_vorrangig: hm.filter((h) => h.art !== 'ergaenzend').reduce((s, h) => s + (Number(h.einheiten) || 0), 0),
  anzahl_vorrangige_heilmittel: hm.filter((h) => h.art === 'vorrangig').length,
  lanr_format_ok: formatOk(vo.lanr),
  bsnr_format_ok: formatOk(vo.bsnr),
  pflichtangaben,
  icd_passende_diagnosegruppe: region,
  diagnosegruppe_passt_zu_icd: region && dg && ['WS', 'EX'].includes(dg) ? region === dg : null,
  leitsymptomatik_zulaessig: leitsymptomatikZulaessig
};
return [{ json: { vo, fakten, diagnose_auswahl: $input.first().json.diagnose_auswahl || { hinweise: [] }, start_ms: Date.now() } }];

// Redigiert Freitext (Chat-Eingang), bevor ihn der Extraktor liest.
// Best effort über Muster – für echte Patientendaten ist der Formularweg gedacht.
const saeubere = (text) => {
  if (typeof text !== "string" || text.trim() === "") return { text, entfernt: [] };
  const entfernt = [];
  let s = text;
  const ersetze = (muster, ersatz, label) => {
    const vorher = s;
    s = s.replace(muster, ersatz);
    if (s !== vorher && !entfernt.includes(label)) entfernt.push(label);
  };

  // Geburtsdatum zuerst – sonst greift die Telefonnummern-Regel (03.04.1958 sieht wie eine Nummer aus)
  ersetze(/\b(?:geb(?:oren|\.)?\s*(?:am)?|Geb\.?-?Datum|Geburtsdatum)\s*:?\s*\d{1,2}\.\d{1,2}\.\d{4}/gi, "[Geburtsdatum]", "Geburtsdatum");

  // Versichertennummer (KVNR: Buchstabe + 8-10 Ziffern) – ICD-Codes haben einen Punkt
  ersetze(/\b[A-Z]{1,2}\d{8,10}\b/g, "[Versichertennummer]", "Versichertennummer");
  ersetze(/[\w.+-]+@[\w-]+\.[\w.]{2,}/g, "[E-Mail]", "E-Mail");
  ersetze(/\b(?:Tel\.?|Telefon|Mobil|Handy|Fax)\s*:?\s*\+?[\d \t/()-]{6,}\d/gi, "[Telefon]", "Telefonnummer");
  // Ziffernfolge wie eine Telefonnummer, aber Datumswerte (03.04.1958) ausnehmen
  ersetze(/(?:\+49|0049|0)[ \t\d/.-]{6,}\d/g, (m) => (/^\d{1,2}\.\d{1,2}\.\d{4}$/.test(m.trim()) ? m : "[Telefon]"), "Telefonnummer");
  ersetze(/\bDE\d{2}(?:[ ]?\d{4}){4}[ ]?\d{2}\b/g, "[IBAN]", "IBAN");
  ersetze(/\b[A-Z]{2}\d{2}(?:[ ]?[A-Z0-9]{4}){2,7}[ ]?[A-Z0-9]{0,2}\b/g, "[IBAN]", "IBAN");
  ersetze(/\bLANR\s*:?\s*\d{6,10}\b/gi, "LANR [LANR]", "LANR");
  ersetze(/\bBSNR\s*:?\s*\d{6,10}\b/gi, "BSNR [BSNR]", "BSNR");

  // Rollenwort + Name (auch Beugungen: Herrn, Patienten, Angehörige …)
  ersetze(/\b(Patient(?:in|en)?|Versicherte(?:r|n)?|Herr(?:n)?|Frau(?:en)?|Kind(?:er)?|Sohn|Tochter|Ehefrau|Ehemann|Lebenspartner(?:in)?|Mutter|Vater|Angehörige(?:r|n)?)\s+(?:Dr\.\s*)?(?:med\.\s*)?[A-ZÄÖÜ][a-zäöüß-]+(?:\s+[A-ZÄÖÜ][a-zäöüß-]+)*/g, (m, rolle) => rolle + " [Name]", "Name");
  // Ärztin/Arzt ohne Rollenwort
  ersetze(/\bDr\.\s*(?:med\.\s*)?(?:dent\.\s*)?[A-ZÄÖÜ][a-zäöüß-]+(?:\s+[A-ZÄÖÜ][a-zäöüß-]+)*/g, "[Arzt]", "Arzt");
  ersetze(/\b(?:Nach)?[Nn]ame\s*:\s*[^\n;,]+/g, "[Name]", "Name");


  // Anschrift: Straße + Hausnummer, PLZ + Ort, Praxisname
  ersetze(/\b[A-ZÄÖÜ][a-zäöüß]+(?:straße|str\.|weg|allee|platz|ring|gasse|damm|ufer)\s*\d+[a-z]?\b/gi, "[Anschrift]", "Anschrift");
  ersetze(/\b\d{5}\s+[A-ZÄÖÜ][a-zäöüß]+(?:\s+[A-ZÄÖÜ][a-zäöüß]+)?/g, "[PLZ Ort]", "Anschrift");
  ersetze(/\bPraxis\s+(?:(?:am|an der|im|für)\s+)?(?:Dr\.\s*(?:med\.\s*)?)?[A-ZÄÖÜ][a-zäöüß-]+(?:\s+[A-ZÄÖÜ][a-zäöüß-]+){0,2}/g, "[Praxis]", "Praxis");

  return { text: s, entfernt };
};
const eingang = $input.first().json;
const { text, entfernt } = saeubere(eingang.text ?? "");
return [{ json: { ...eingang, text, redaktion: { entfernt } } }];

// Wählt die zwei ICD-10-GM-Zeilen des Vordrucks Muster 13 aus der Liste der erkannten
// Diagnosen. Regel: docs/vordruck-muster13.md, Abschnitt 5. Deterministisch – die
// Diagnosegruppe des Heilmittels entscheidet, welcher Code verordnungsrelevant ist.
const vo = $input.first().json.output;

// ICD-10-Bereich -> Körperregion (dieselbe Zuordnung wie im Code-Node "Fristen berechnen")
const icdRegion = (code) => {
  if (!code) return null;
  const m = String(code).toUpperCase().match(/^([A-Z])(\d{2})/);
  if (!m) return null;
  const k = m[1], n = Number(m[2]);
  if (k === 'M' && n >= 40 && n <= 54) return 'WS';
  if (k === 'S' && [12, 13, 22, 23, 32, 33].includes(n)) return 'WS';
  if (k === 'M' && n >= 15 && n <= 25) return 'EX';
  if (k === 'M' && [75, 76, 77].includes(n)) return 'EX';
  if (k === 'S' && n >= 40 && n <= 99) return 'EX';
  return null;
};

// 1. Sammeln: alle genannten Codes, ohne Doppelte, in der Reihenfolge der Nennung.
const erkannt = [];
const roh = Array.isArray(vo.diagnosen) && vo.diagnosen.length
  ? vo.diagnosen
  : (vo.icd10 ? [{ code: vo.icd10, bezeichnung: vo.icd10_bezeichnung || null, anlass: true }] : []);
for (const d of roh) {
  const code = d && d.code ? String(d.code).toUpperCase().trim() : null;
  if (code && !erkannt.some((e) => e.code === code)) {
    erkannt.push({ code, bezeichnung: d.bezeichnung || null, anlass: !!d.anlass });
  }
}

// 2. Verordnungsbezug: Ein Code ist relevant, wenn er zur Diagnosegruppe passt.
const dg = vo.diagnosegruppe ? String(vo.diagnosegruppe).toUpperCase().trim() : null;
const passt = (d) => !!dg && icdRegion(d.code) === dg;
const nachAnlass = (a, b) => Number(b.anlass) - Number(a.anlass);
const relevant = erkannt.filter(passt).sort(nachAnlass);

// 3. Zeile 1 = führende Diagnose (Anlass, sonst erster relevanter Code), Zeile 2 = nächster relevanter Code.
const fuehrend = relevant[0] || [...erkannt].sort(nachAnlass)[0] || null;
const zweite = fuehrend ? relevant.filter((d) => d.code !== fuehrend.code)[0] || null : null;

const hinweise = [];
