  hinweise.push('Kein ICD-10-GM-Code erkannt – Zeile 1 bleibt leer.');
} else if (!relevant.length) {
  hinweise.push('Kein erkannter Code passt zur Diagnosegruppe ' + (dg || '(keine)') + '; Zeile 1 ist ein Vorschlag und fachlich zu prüfen.');
}
if (relevant.length > 2) {
  hinweise.push(relevant.length + ' Codes passen zur Diagnosegruppe ' + dg + ' – Zeile 2 folgt der Nennungsreihenfolge, die übrigen fachlich prüfen.');
}

// 4. Alles Übrige nachvollziehbar begründen – es wird nichts stillschweigend verworfen.
vo.icd10 = fuehrend ? fuehrend.code : null;
vo.icd10_bezeichnung = fuehrend ? fuehrend.bezeichnung : null;
vo.weitere_diagnosen = zweite ? [{ code: zweite.code, bezeichnung: zweite.bezeichnung }] : [];
vo.nicht_verordnungsrelevant = erkannt.filter((d) => !fuehrend || d.code !== fuehrend.code).filter((d) => !zweite || d.code !== zweite.code).map((d) => {
  const region = icdRegion(d.code);
  return {
    code: d.code,
    bezeichnung: d.bezeichnung,
    grund: region === null
      ? 'Körperregion nicht zuordenbar – nur bei besonderem Verordnungsbedarf über die Diagnoseliste relevant'
      : 'andere Körperregion (' + region + ') als die Diagnosegruppe ' + dg
  };
});

return [{ json: {
  output: vo,
  diagnose_auswahl: {
    fuehrend: fuehrend ? { code: fuehrend.code, bezeichnung: fuehrend.bezeichnung, anlass: fuehrend.anlass } : null,
    zweite: zweite ? { code: zweite.code, bezeichnung: zweite.bezeichnung, anlass: zweite.anlass } : null,
    erkannt: erkannt.length,
    hinweise
  }
} }];

// PII-Redaktion: Die Prüf-Agenten erhalten nur die fachlich nötigen Angaben.
// Direkte Identifikatoren werden durch Marker ersetzt (das Feld bleibt als "ausgefüllt"
// erkennbar), freie Texte entfernt oder bereinigt. Das Original bleibt im Prüfprotokoll.
const saeubere = (text) => {
  if (typeof text !== "string" || text.trim() === "") return { text, entfernt: [] };
  const entfernt = [];
  let s = text;
  const ersetze = (muster, ersatz, label) => {
    const vorher = s;
    s = s.replace(muster, ersatz);
    if (s !== vorher && !entfernt.includes(label)) entfernt.push(label);
  };

  // Geburtsdatum zuerst – sonst greift die Telefonnummern-Regel (03.04.1958 sieht wie eine Nummer aus)
  ersetze(/\b(?:geb(?:oren|\.)?\s*(?:am)?|Geb\.?-?Datum|Geburtsdatum)\s*:?\s*\d{1,2}\.\d{1,2}\.\d{4}/gi, "[Geburtsdatum]", "Geburtsdatum");

  // Versichertennummer (KVNR: Buchstabe + 8-10 Ziffern) – ICD-Codes haben einen Punkt
  ersetze(/\b[A-Z]{1,2}\d{8,10}\b/g, "[Versichertennummer]", "Versichertennummer");
  ersetze(/[\w.+-]+@[\w-]+\.[\w.]{2,}/g, "[E-Mail]", "E-Mail");
  ersetze(/\b(?:Tel\.?|Telefon|Mobil|Handy|Fax)\s*:?\s*\+?[\d \t/()-]{6,}\d/gi, "[Telefon]", "Telefonnummer");
  // Ziffernfolge wie eine Telefonnummer, aber Datumswerte (03.04.1958) ausnehmen
  ersetze(/(?:\+49|0049|0)[ \t\d/.-]{6,}\d/g, (m) => (/^\d{1,2}\.\d{1,2}\.\d{4}$/.test(m.trim()) ? m : "[Telefon]"), "Telefonnummer");
  ersetze(/\bDE\d{2}(?:[ ]?\d{4}){4}[ ]?\d{2}\b/g, "[IBAN]", "IBAN");
  ersetze(/\b[A-Z]{2}\d{2}(?:[ ]?[A-Z0-9]{4}){2,7}[ ]?[A-Z0-9]{0,2}\b/g, "[IBAN]", "IBAN");
  ersetze(/\bLANR\s*:?\s*\d{6,10}\b/gi, "LANR [LANR]", "LANR");
  ersetze(/\bBSNR\s*:?\s*\d{6,10}\b/gi, "BSNR [BSNR]", "BSNR");

  // Rollenwort + Name (auch Beugungen: Herrn, Patienten, Angehörige …)
  ersetze(/\b(Patient(?:in|en)?|Versicherte(?:r|n)?|Herr(?:n)?|Frau(?:en)?|Kind(?:er)?|Sohn|Tochter|Ehefrau|Ehemann|Lebenspartner(?:in)?|Mutter|Vater|Angehörige(?:r|n)?)\s+(?:Dr\.\s*)?(?:med\.\s*)?[A-ZÄÖÜ][a-zäöüß-]+(?:\s+[A-ZÄÖÜ][a-zäöüß-]+)*/g, (m, rolle) => rolle + " [Name]", "Name");
  // Ärztin/Arzt ohne Rollenwort
  ersetze(/\bDr\.\s*(?:med\.\s*)?(?:dent\.\s*)?[A-ZÄÖÜ][a-zäöüß-]+(?:\s+[A-ZÄÖÜ][a-zäöüß-]+)*/g, "[Arzt]", "Arzt");
  ersetze(/\b(?:Nach)?[Nn]ame\s*:\s*[^\n;,]+/g, "[Name]", "Name");


  // Anschrift: Straße + Hausnummer, PLZ + Ort, Praxisname
  ersetze(/\b[A-ZÄÖÜ][a-zäöüß]+(?:straße|str\.|weg|allee|platz|ring|gasse|damm|ufer)\s*\d+[a-z]?\b/gi, "[Anschrift]", "Anschrift");
  ersetze(/\b\d{5}\s+[A-ZÄÖÜ][a-zäöüß]+(?:\s+[A-ZÄÖÜ][a-zäöüß]+)?/g, "[PLZ Ort]", "Anschrift");
  ersetze(/\bPraxis\s+(?:(?:am|an der|im|für)\s+)?(?:Dr\.\s*(?:med\.\s*)?)?[A-ZÄÖÜ][a-zäöüß-]+(?:\s+[A-ZÄÖÜ][a-zäöüß-]+){0,2}/g, "[Praxis]", "Praxis");

  return { text: s, entfernt };
};
const basis = $input.first().json;
const vo = basis.vo ?? {};
const entfernt = [];

const marke = (wert, label) => {
  if (wert === null || wert === undefined || String(wert).trim() === "") return null;
  if (!entfernt.includes(label)) entfernt.push(label);
  return "[" + label + "]";
};
const freitext = (wert, label) => {
  if (!wert) return null;
  if (!entfernt.includes(label)) entfernt.push(label);
  return "[Freitext entfernt]";
};
const bereinigt = (wert) => {
  const { text, entfernt: gefunden } = saeubere(wert ?? "");
  for (const g of gefunden) if (!entfernt.includes(g)) entfernt.push(g);
  return text === "" ? null : text;
};

const redigiert = {
  ...vo,
  patient: {
    krankenkasse: vo.patient?.krankenkasse ?? null,
    nachname: marke(vo.patient?.nachname, "Name"),
    vorname: marke(vo.patient?.vorname, "Vorname"),
    geburtsdatum: marke(vo.patient?.geburtsdatum, "Geburtsdatum"),
    kostentraegerkennung: marke(vo.patient?.kostentraegerkennung, "Kostenträgerkennung"),
    versichertennummer: marke(vo.patient?.versichertennummer, "Versichertennummer"),
    versichertenstatus: vo.patient?.versichertenstatus ?? null
  },
  lanr: marke(vo.lanr, "LANR"),
  bsnr: marke(vo.bsnr, "BSNR"),
  arzt: {
    name: marke(vo.arzt?.name, "Arzt"),
    fachrichtung: vo.arzt?.fachrichtung ?? null,
    betriebsstaette: marke(vo.arzt?.betriebsstaette, "Praxis")
  },
  icd10_bezeichnung: bereinigt(vo.icd10_bezeichnung),
  weitere_diagnosen: (vo.weitere_diagnosen ?? []).map((d) => ({ ...d, bezeichnung: bereinigt(d.bezeichnung) })),
  diagnosen: (vo.diagnosen ?? []).map((d) => ({ ...d, bezeichnung: bereinigt(d.bezeichnung) })),
  nicht_verordnungsrelevant: (vo.nicht_verordnungsrelevant ?? []).map((d) => ({ ...d, bezeichnung: bereinigt(d.bezeichnung) })),
  leitsymptomatik_freitext: freitext(vo.leitsymptomatik_freitext, "Leitsymptomatik-Freitext"),
  therapieziele_hinweise: freitext(vo.therapieziele_hinweise, "Therapieziele"),
  unterbrechungsgrund: bereinigt(vo.unterbrechungsgrund),
  pseudonymisiert: true
};

// Wichtig: `vo` wird ersetzt, nicht ergänzt – sonst ginge das Original mit an das Modell.
return [{ json: { ...basis, vo: redigiert, pii: { pseudonymisiert: true, entfernt } } }];

