const VERGUETUNG_PRO_EINHEIT_EUR = 28; // Annahme fuer den Business Case, im Ist-Interview verifizieren
const basis = $('Fristen berechnen').first().json;
const vo = basis.vo;
const labels = { formal: 'Formal-Prüfer', diagnose: 'Diagnose-Prüfer', menge: 'Mengen-Prüfer', frist: 'Fristen-Prüfer' };
const icon = { ok: '✅', fehlt: '❌', fehlerhaft: '❌', hinweis: '⚠️' };
const clean = (s) => String(s || '').replace(/\|/g, '/').replace(/\n/g, ' ');
const befunde = [];
for (const item of $input.all()) {
  const r = item.json.output || {};
  for (const b of r.befunde || []) {
    befunde.push({ agent: r.agent, feld: b.feld, status: b.status, fundstelle: b.fundstelle || null, korrekturhinweis: b.korrekturhinweis || null });
  }
}
const kritisch = befunde.filter((b) => b.status === 'fehlt' || b.status === 'fehlerhaft');
const hinweise = befunde.filter((b) => b.status === 'hinweis');
const gesamtstatus = kritisch.length ? 'rot' : hinweise.length ? 'gelb' : 'gruen';
const einheiten = basis.fakten.summe_einheiten || 0;
const risiko = gesamtstatus === 'rot' ? einheiten * VERGUETUNG_PRO_EINHEIT_EUR : 0;
const ampel = {
  rot: '🔴 Bitte nicht behandeln – Verordnung erst korrigieren lassen',
  gelb: '🟡 Behandlung möglich – Hinweise beachten',
  gruen: '🟢 Verordnung in Ordnung'
}[gesamtstatus];
let antwort = '**Verordnungs-Check ' + (vo.verordnung_ref || '') + '**\n\n' + ampel + '\n\n';
if (risiko) antwort += 'Absetzungsrisiko: ca. ' + risiko + ' € (' + einheiten + ' Einheiten × ' + VERGUETUNG_PRO_EINHEIT_EUR + ' €, Annahme)\n\n';
const relevant = kritisch.concat(hinweise);
if (relevant.length) {
  antwort += '| Prüfer | Feld | Status | Was tun? | Fundstelle |\n|---|---|---|---|---|\n';
  for (const b of relevant) {
    antwort += '| ' + (labels[b.agent] || b.agent) + ' | ' + clean(b.feld) + ' | ' + icon[b.status] + ' ' + b.status + ' | ' + clean(b.korrekturhinweis) + ' | ' + clean(b.fundstelle) + ' |\n';
  }
}
antwort += '\n' + befunde.length + ' Prüfpunkte von 4 Prüfern, davon ' + befunde.filter((b) => b.status === 'ok').length + ' in Ordnung.';
return [{ json: {
  verordnung_ref: vo.verordnung_ref || 'ohne Referenz',
  eingabe: { verordnung: vo, fakten: basis.fakten },
  gesamtstatus,
  absetzungsrisiko_eur: risiko,
  zusammenfassung: ampel,
  dauer_ms: Date.now() - basis.start_ms,
  freigabe: 'offen',
  diagnose_auswahl: basis.diagnose_auswahl || { hinweise: [] },
  befunde,
  antwort
} }];

const pruefungId = $input.first().json.id;
const befunde = $('Ergebnis zusammenführen').first().json.befunde || [];
return befunde.map((b) => ({ json: { pruefung_id: pruefungId, agent: b.agent, feld: b.feld, status: b.status, fundstelle: b.fundstelle, korrekturhinweis: b.korrekturhinweis } }));
